"""Generate static layout drafts only; no game UI or behavior."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).parent
PAGES = {
 'P02': ('主菜单', [(40,30,1360,70,'DeiDei · 当前昵称 / 头像 · 版本示例'),(400,250,640,150,'单人 → P03'),(400,430,640,150,'联机 → P04'),(400,630,640,70,'规则 P11 / 设置 P10 / 退出'),(40,800,1360,60,'断网提示：仅影响联机，单人仍可用')]),
 'P04': ('创建 / 加入房间', [(40,30,1360,70,'DeiDei · 创建 / 加入房间 · 返回 P02'),(80,140,610,540,'创建房间|房名（可选）|参战位：2—6|密码（可选）|创建 → P05'),(750,140,610,540,'加入房间|房间号（不限定示例位数）|密码（需要时显示）|参战 / 观战|加入 → P05'),(80,720,1280,130,'错误状态示例（按情况显示）|连接失败 / 房间不存在 / 密码错误|参战已满 / 观众已满 / 版本不兼容')]),
 'P05': ('房间等候', [(40,30,1360,70,'房间号 / 复制 · 房主：玩家 01 · 经典模式'), *[(80+(i%3)*310,170+(i//3)*190,280,150,f'席位 {i+1:02}|'+(['玩家 01 · 房主','玩家 02 · 已准备','玩家 03 · 未准备','空位','空位','空位'][i])) for i in range(6)],(1050,170,310,340,'观众区|观众人数 / 容量待定|等待下一局参战'),(80,590,1280,90,'至少两位真人才可开始 · 容量按创建时显示'),(80,720,1280,120,'准备 / 房主开始 / 离开|房主离开确认：离开将结束房间')]),
 'P06': ('双人牌桌', [(40,30,1360,60,'菜单 / 快捷发言 · 回合示例'),(530,120,380,130,'玩家 02 · DD 示例|等待提交 / 托管标记'),(240,290,960,300,'中央公开战况|未揭晓前不展示对方动作'),(40,610,1360,70,'倒计时：示例（时长待定）'),(40,710,220,140,'玩家 01 · 自己|本人 DD 示例'),(290,710,800,140,'本人卡牌：招式占位 / 说明|资源不足状态'),(1120,710,280,140,'提交（示意）|等待对方 / 断线提示')]),
 'P07': ('六人牌桌', [(40,30,1360,60,'菜单 / 快捷发言 · 回合示例'),(350,110,340,120,'玩家 02 · DD 示例|存活 / 已提交'),(750,110,340,120,'玩家 03 · DD 示例|存活 / 思考中'),(40,280,230,130,'玩家 04 · DD 示例|存活 / 思考中'),(40,440,230,130,'玩家 05 · DD 示例|已淘汰'),(1170,340,230,150,'玩家 06 · DD 示例|存活 / 已提交'),(300,260,840,320,'中央公开战况|无选目标步骤 / 隐藏未揭晓动作'),(40,610,1360,70,'倒计时：示例（时长待定）'),(40,710,230,140,'玩家 01 · 自己|本人 DD 示例'),(300,710,800,140,'本人卡牌：招式占位 / 说明|超时默认攒 · 资源不足提示'),(1130,710,270,140,'提交（示意）|本人已提交 / 断线')]),
 'P08': ('观战 / 本人淘汰', [(40,30,1360,60,'观战身份 · 回合示例 · 菜单'),*[(x,y,w,h,f'玩家 {i+1:02} · 公开 DD 示例|'+('已淘汰' if i==4 else '存活 / 提交状态')) for i,(x,y,w,h) in enumerate([(40,530,270,120),(350,110,340,120),(750,110,340,120),(40,260,270,120),(40,400,270,120),(1130,320,270,140)])],(340,260,760,340,'中央公开战况 / 已揭晓记录|未揭晓动作不可见'),(40,700,960,150,'观战中 · 无个人可出手牌|留房等待下一局（本局不复活）|本人淘汰变体：你已淘汰，可观战或退出'),(1030,700,370,150,'留房 / 退出')])}

def main() -> None:
    for page, (title, boxes) in PAGES.items():
        parts=['<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="900" viewBox="0 0 1440 900"><rect width="1440" height="900" fill="#faf9f6"/><g font-family="PingFang SC, sans-serif" font-size="23" fill="#333">']
        for x,y,w,h,label in boxes:
            parts.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="#fff" stroke="#888" stroke-width="2"/>')
            for j,line in enumerate(label.split('|')):
                parts.append(f'<text x="{x+18}" y="{y+32+j*36}">{escape(line)}</text>')
        if page in ('P06', 'P07'):
            parts.append('<rect x="660" y="638" width="600" height="14" rx="7" fill="#ddd"/><rect x="660" y="638" width="380" height="14" rx="7" fill="#7b99a4"/>')
        parts.append(f'<text x="40" y="888" font-size="16">{page} · {title} · wireframe v1 · 静态排布草稿</text></g></svg>')
        (ROOT/f'{page}-wireframe-v1.svg').write_text(''.join(parts))
    assert len(list(ROOT.glob('P*-wireframe-v1.svg'))) == 6

if __name__ == '__main__':
    main()
